@Service
public class OrderService {
    private final WebClient inventoryClient;

    public OrderService(WebClient.Builder builder) {
        this.inventoryClient = builder.baseUrl("http://inventory-service").build();
    }

    public Order createOrder(OrderRequest request) {
        // Call InventoryService to check stock
        var stockResponse = inventoryClient.get()
            .uri("/api/inventory/{productId}", request.productId())
            .retrieve()
            .bodyToMono(StockResponse.class)
            .block(); // Blocking call for simplicity

        if (stockResponse.available() < request.quantity()) {
            throw new OutOfStockException("Not enough inventory");
        }

        var order = new Order(request.productId(), request.quantity(), "PENDING");
        return orderRepository.save(order);
        // In real code, you'd also call InventoryService to reserve stock
    }
}

