// MONOLITH: one app, one DB, an in-process call wrapped in one transaction
@Service
class CheckoutService {
    @Transactional
    public void checkout(Order order) {
        orderRepo.save(order);
        inventoryRepo.decrement(order.productId()); // same DB, atomic
    }
}

// MICROSERVICES: separate services over the network, no shared transaction
@Service
class OrderService {
    private final WebClient inventory; // points at inventory-service
    public void checkout(Order order) {
        orderRepo.save(order);                    // OrderService DB
        inventory.post().uri("/reserve")          // network call
            .bodyValue(order).retrieve()
            .toBodilessEntity().block();          // can fail independently
    }
}
