// Synchronous: call another service and WAIT for the response (REST)
@Service
class OrderService {
    private final WebClient payment;
    public PaymentResult charge(Order order) {
        return payment.post().uri("/charge")
            .bodyValue(order).retrieve()
            .bodyToMono(PaymentResult.class)
            .block(); // blocks until PaymentService answers
    }
}

// Asynchronous: publish an event and move on (Kafka) — consumers react later
@Service
class OrderEvents {
    private final KafkaTemplate<String, OrderPlaced> kafka;
    public void publish(Order order) {
        kafka.send("orders", new OrderPlaced(order.id())); // fire and forget
    }
}
