// Monolith: atomic transaction
@Transactional
public void placeOrder(Order order) {
    orderRepository.save(order);
    inventoryRepository.decrementStock(order.productId());
    // Both succeed or both rollback automatically
}

// Microservices: no shared transaction
public void placeOrder(Order order) {
    var savedOrder = orderService.createOrder(order); // HTTP call to OrderService
    try {
        inventoryService.reserveStock(order.productId()); // HTTP call to InventoryService
    } catch (Exception e) {
        // Inventory failed, but order is already saved!
        // Need compensating transaction to cancel order
        orderService.cancelOrder(savedOrder.id());
        throw new OrderFailedException("Could not reserve inventory");
    }
    // What if cancelOrder fails? Need Saga pattern or outbox pattern
}

