// MonolithFirst: build a well-structured MODULAR monolith. Each module is a
// clean package with a clear interface you can later extract without rewiring.
package com.shop.inventory;             // module boundary

public interface InventoryService {     // the contract callers depend on
    boolean reserve(String productId, int qty);
}

// In the monolith: a simple in-process bean
@Service
class LocalInventoryService implements InventoryService { /* local DB */ }

// Extract LATER, only when real pain appears (scaling or team coordination):
// swap the implementation for a REST client — callers never change.
@Service
class RemoteInventoryService implements InventoryService {
    private final WebClient client; // now calls inventory-service over HTTP
    public boolean reserve(String id, int qty) { /* network call */ return true; }
}
